window.kbPageData["views/entry/k-ac3a95a6c705c715"] = {"key":"entry/k-ac3a95a6c705c715","state":{"route":"entry/k-ac3a95a6c705c715"},"node":{"id":"k-ac3a95a6c705c715","mode":"k","title":"互斥类别的占比上限","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["互斥类别中的某一类占比不超过扣除其他已知类别后的剩余占比"],"qs":["江苏 2025 B类 行测#135"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"在同一总体中，若目标类别与各已知类别互斥，且各已知类别之间也互斥，则目标类别的占比至多等于100%减去各已知类别的占比之和。只有剩余成员全部属于目标类别时，才达到这个上限。","review":{"definition":"在同一总体中，若目标类别与各已知类别互斥，且各已知类别之间也互斥，则目标类别的占比至多等于100%减去各已知类别的占比之和。只有剩余成员全部属于目标类别时，才达到这个上限。","explanation":"第135题以2023年末全国公共图书馆从业人员为总体，高级和中级职称人员分别占13.0%和31.2%，合计44.2%。初级职称人员只能来自其余55.8%的从业人员。材料未说明其余人员是否都具有初级职称，因此只能推出初级职称从业人员占比不超过55.8%，对应D项。","references":[],"evidence":"中、高级职称从业人员占比=13.0%+31.2%=44.2%","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 B类 行测#135":{"paper":"江苏 2025 B类 行测","n":135,"mod":"资料分析","src":["91e0d9fd02ca7ec6d61f.pdf",27],"asrc":["f2ff67a0f2a2f7e8e926.pdf",44],"card":"4bd02713a7119a2e2edf1fc0","links":[{"id":"k-ac3a95a6c705c715","role":"解题依据","why":"扣除中、高级职称人员后，初级职称人员只可能占剩余人员的全部或一部分。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-ac3a95a6c705c715":[["江苏 2025 B类 行测#135"]]}};
